    <div className={className || `content-stretch flex flex-col items-start px-[var(--mnd-study-space-16,16px)] py-[var(--mnd-study-space-12,12px)] relative rounded-[var(--mnd-mobile-v2-radius-card,16px)] w-[300px] ${isMine ? "bg-[var(--mnd-study-color-brandsoft,#fff1eb)]" : "bg-[var(--mnd-study-color-surface,#fffefc)]"}`} id={isMine ? "node-105_378" : "node-105_377"}>
      {side === "Theirs" && (
        <p className="[word-break:break-word] font-['Noto_Sans_SC:Regular'] font-normal leading-[26px] relative shrink-0 text-[16px] text-[color:var(--mnd-study-color-ink,#202329)] w-[268px]" data-node-id="105:380">
          {message}
        </p>
      )}
      {isMine && (
        <p className="[word-break:break-word] font-['Noto_Sans_SC:Regular'] font-normal leading-[26px] relative shrink-0 text-[16px] text-[color:var(--mnd-study-color-brand,#9e382a)] w-[268px]" data-node-id="105:381">
          {message}
        </p>
      )}
